  const partError=decisions.some(d=>d.assigned>d.line.requested||d.accepted>(active?.scanned.find(s=>s.item_id===d.line.item_id)?.quantity??0));
  const full=decisions.length>0&&decisions.every(d=>d.assigned===d.line.requested)&&!partError;
  const label=(l:Line,currency=active?.order.currency??'')=>`Pozycja ${l.ordinal} · ${l.sku} — ${l.name} · oryginalnie ${l.original_quantity} szt.${l.line_total==null?'':` / ${money(l.line_total,currency)} za całą pozycję`}`;
