  async function showPhoto(p:Photo){await run(async()=>{const g=epoch.current,d=await api<Flags&{photo_id:string;mime:string;content_base64:string;byte_count:number;sha256:string}>(prefix+'/photos/'+p.id+'/content');if(!current(g))throw Error('Kontekst firmy zmienił się.');acceptFlags(d);if(d.photo_id!==p.id||d.sha256!==p.sha256||d.byte_count!==p.byte_count||d.mime!==p.mime||typeof d.content_base64!=='string'||d.content_base64.length>1398104)throw Error('Zdjęcie nie odpowiada zapisanej kontroli.');const bytes=Uint8Array.from(atob(d.content_base64),c=>c.charCodeAt(0)),digest=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))).map(v=>v.toString(16).padStart(2,'0')).join('');if(bytes.length!==p.byte_count||digest!==p.sha256)throw Error('Suma kontrolna zdjęcia nie zgadza się.');return{id:p.id,url:`data:${p.mime};base64,${d.content_base64}`};},setPhotoView);}
